// --- Pull window_days / is_scheduled_run from the upstream Set node ---
const windowNode = $('Resolve Window').first().json;
const windowDays = windowNode.window_days; // 0/falsy => full history, no comparison
const isScheduledRun = windowNode.is_scheduled_run || false;

// --- Pull all Applications rows from the Google Sheets read node ---
const rows = $('Read Applications').all().map(item => item.json);

function parseTs(tsStr) {
  if (!tsStr) return null;
  const d = new Date(tsStr);
  return isNaN(d.getTime()) ? null : d;
}

const now = new Date();

function inWindow(row, start, end) {
  const ts = parseTs(row.timestamp);
  if (ts === null) return false;
  return ts >= start && ts < end;
}

let currentRows, priorRows, hasComparison;

if (windowDays) {
  const currentStart = new Date(now.getTime() - windowDays * 24 * 60 * 60 * 1000);
  currentRows = rows.filter(r => inWindow(r, currentStart, now));

  const priorStart = new Date(now.getTime() - windowDays * 2 * 24 * 60 * 60 * 1000);
  const priorEnd = currentStart;
  priorRows = rows.filter(r => inWindow(r, priorStart, priorEnd));
  hasComparison = true;
} else {
  currentRows = rows;
  priorRows = [];
  hasComparison = false;
}

function safeFloat(val, defaultVal = 0.0) {
  const n = parseFloat(val);
  return isNaN(n) ? defaultVal : n;
}

function computePeriodStats(periodRows) {
  const total = periodRows.length;
  const scores = periodRows
    .filter(r => r.match_score !== null && r.match_score !== undefined && r.match_score !== '')
    .map(r => safeFloat(r.match_score));
  const avgScore = scores.length
    ? Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 100) / 100
    : 0;

  const recCounts = { strong: 0, partial: 0, weak: 0 };
  for (const r of periodRows) {
    const decision = String(r.decision || '').trim().toLowerCase();
    if (decision === 'strong match') recCounts.strong += 1;
    else if (decision === 'partial match') recCounts.partial += 1;
    else if (decision === 'weak match') recCounts.weak += 1;
  }

  const coverLettersGenerated = periodRows.filter(r =>
    ['true', 'yes', '1'].includes(String(r.cover_letter_generated || '').trim().toLowerCase())
  ).length;
  const coverLetterRate = total
    ? Math.round((coverLettersGenerated / total) * 100) / 100
    : 0;

  return {
    total_applications: total,
    avg_match_score: avgScore,
    strong_match_count: recCounts.strong,
    partial_match_count: recCounts.partial,
    weak_match_count: recCounts.weak,
    cover_letters_generated: coverLettersGenerated,
    cover_letter_generation_rate: coverLetterRate,
  };
}
const currentStats = computePeriodStats(currentRows);

const result = {
  window_days: windowDays,
  is_scheduled_run: isScheduledRun,
  has_comparison: hasComparison,
  current_period: currentStats,
};

if (hasComparison) {
  const priorStats = computePeriodStats(priorRows);
  result.prior_period = priorStats;

  const delta = (curr, prev) => Math.round((curr - prev) * 100) / 100;

  result.deltas = {
    total_applications: delta(currentStats.total_applications, priorStats.total_applications),
    avg_match_score: delta(currentStats.avg_match_score, priorStats.avg_match_score),
    cover_letter_generation_rate: delta(
      currentStats.cover_letter_generation_rate,
      priorStats.cover_letter_generation_rate
    ),
  };
}

// --- Raw gap strings from the current period, for the LLM to cluster into themes ---
result.gaps_identified_raw = currentRows
  .map(r => (r.gaps_identified || '').trim())
  .filter(g => g.length > 0);

return [{ json: result }];
